import { PROMPT_LANGUAGES, type PromptLanguage } from './types';

/** Native Tutor instruction packs. JSON keys and enum values are intentionally
 * invariant; only human-facing instructions are translated. */
export interface TutorPromptPack { plan: string; directed: string; overview: string; repair: string; step: string }

/** Runtime copy used by the deterministic Tutor boundary. Protocol keys, IDs,
 * enum values, and validation rules stay outside this pack. */
export interface TutorRuntimeCopy {
  edgeTypeLabels: Record<string, string>;
  weightLabels: Record<1 | 2 | 3 | 4 | 5, string>;
  stopFallback: string;
  routeFallback: string;
  overviewFallback: string;
  coverageCriterion: string;
  contextKinds: { theme: string; connection: string; idea: string };
  errors: { emptyGraph: string; invalidPlan: string; invalidStop: string };
}

