export function tutorLanguage(language: unknown = 'es'): PromptLanguage {
  return typeof language === 'string' && PROMPT_LANGUAGES.includes(language as PromptLanguage) ? language as PromptLanguage : 'es';
}

export function tutorRuntimeCopy(language: unknown = 'es'): TutorRuntimeCopy {
  return TUTOR_RUNTIME_COPY[tutorLanguage(language)];
}

